import {works} from './catalog.js';
import {portraits} from './portraits.js';
const discoveryOrder=["sample-female-quiet-bookbinder","sample-cold-editor","sample-female-unreleased-track","sample-silver","sample-female-frail-cartographer","sample-female-anonymous-credit","sample-female-seasonal-engagement","sample-dragon","sample-female-midnight-postscript","sample-sori","sample-female-forgetful-spring","sample-warm","sample-female-unwritten-constellation","sample-succubus","sample-female-dual-return-order","sample-suit","sample-female-storm-return-map","sample-violet","sample-deer","sample-slime","sample-gumiho","sample-crow","sample-muse","sample-whitesnake","sample-ruby","sample-dokkaebi","sample-serpent","sample-female-final-curtain-bet","sample-ram-demon"];
const editorialWorks=[...works].sort((a,b)=>(discoveryOrder.includes(a.id)?discoveryOrder.indexOf(a.id):discoveryOrder.length+works.indexOf(a))-(discoveryOrder.includes(b.id)?discoveryOrder.indexOf(b.id):discoveryOrder.length+works.indexOf(b)));
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog'),toast=document.querySelector('#toast');
const state={view:'home',work:null,opening:0,detail:'info',audience:'전체',genre:'전체',query:'',feature:0,paused:false,persona:{name:'',role:'',description:''},messages:[],balance:120,transactions:[],tracker:{place:'첫 만남의 장소',time:'이야기의 시작',relationship:'첫 만남',memo:''},font:17,art:true,creatorDraft:null,createdDraft:null,createdWork:null,creatorStep:0,creatorError:'',creatorReturn:null,localWorks:[],sessions:[],activeSession:null,editingWorkId:null,nextWork:1,nextSession:1,worksArchived:false,chatsArchived:false,collectionQuery:'',settingsSection:'library',libraryTab:'personas',layoutFields:['장소','시간','관계','메모'],chatBookmarks:[],chatNotes:'',chatMemory:'',selectedCast:0,chatArt:'cover',sharedImported:false,studioTab:'collected',savedPersona:{name:'',role:'',description:''}};
const E=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,text,klass='secondary',attrs='')=>`<button type="button" class="${klass}" data-action="${action}" ${attrs}>${text}</button>`;
const icons={close:'×',back:'‹',next:'›',menu:'☰',asset:'▧',snapshot:'▣',tracker:'▤'};
const featured=()=>['sample-female-quiet-bookbinder','sample-cold-editor','sample-female-final-curtain-bet','sample-dragon'].map(id=>works.find(w=>w.id===id)).filter(Boolean);
const rating=w=>`<span class="rating ${w.rating==='19+'?'adult':'all'}">${w.rating==='19+'?'19+':'전체'}</span>`;
const cardSizes='(max-width: 640px) calc((100vw - 50px) / 2), (max-width: 900px) calc((100vw - 108px) / 3), (max-width: 1150px) calc((100vw - 124px) / 4), 246px';
function responsive(w,sizes=cardSizes){const p=portraits[w.cover];return p?`width="${p.width}" height="${p.height}" srcset="${p.variants.map(v=>'.'+v.src+' '+v.width+'w').concat('.'+w.cover+' '+p.width+'w').join(', ')}" sizes="${sizes}"`:''}
const portrait=(w,sizes=cardSizes)=>`<img src=".${E(w.cover)}" ${responsive(w,sizes)} alt="${E(w.characters[0].name)} 일러스트" loading="lazy" decoding="async">`;
function notify(text){toast.textContent=text;toast.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>toast.classList.remove('show'),3500)}
function prose(text){return E(text).split(/\n\s*\n/).map(p=>`<p>${p}</p>`).join('')}
function dialogue(text,authoredSeed=true){let parts;if(text.includes('*'))parts=text.split(/(\*[^*]+\*)/g).filter(x=>x.trim()).map(x=>({action:x.startsWith('*')&&x.endsWith('*'),text:x.startsWith('*')&&x.endsWith('*')?x.slice(1,-1).trim():x.trim()}));else if(!authoredSeed)parts=text.split(/\n\s*\n/).filter(x=>x.trim()).map(x=>({action:false,text:x.trim()}));else parts=text.split(/(“[^”]*”|"[^"\n]*")/g).filter(x=>x.trim()).map(x=>({action:!/^([“"])/.test(x.trim()),text:x.trim()}));return `<div class="dialogue-prose">${parts.map(p=>`<p class="dialogue-block ${p.action?'action-block':'speech-block'}">${p.action?`<em class="action-text">${E(p.text)}</em>`:`<span class="dialogue-text">${E(p.text)}</span>`}</p>`).join('')}</div>`}
const approvedCharacterImages=new Set(works.flatMap(w=>[w.cover,...w.characters.map(c=>c.portrait).filter(Boolean)]));
const characterSource=(w,c)=>c?.portrait&&approvedCharacterImages.has(c.portrait)?c.portrait:w.cover;
const characterAge=c=>c.ageLabel||(typeof c.age==='number'?c.age+'세':'나이 미설정');
function turnText(w,t){const c=w.characters.find(c=>c.id===t.characterId);return c?c.name+': '+t.content:t.content}
function speaker(w,text){const t=w.sampleTurns?.find(t=>turnText(w,t)===text);return t?{character:w.characters.find(c=>c.id===t.characterId),content:t.content}:null}
function chatArtCharacter(w){return w.characters.find(c=>'cast:'+c.id===state.chatArt)}
function chatArtSource(w){return characterSource(w,chatArtCharacter(w))}
function castPicker(w){return w.characters.length>1?`<div class="cast-picker" aria-label="등장인물 선택">${w.characters.map((c,i)=>button('select-cast',`${portrait({...w,cover:characterSource(w,c),characters:[c]},'80px')}<span>${E(c.name)}</span>`,state.selectedCast===i?'selected':'',`data-index="${i}" aria-label="${E(c.name)}" aria-pressed="${state.selectedCast===i}"`)).join('')}</div>`:''}
function messageMarkup(m,w,index){const voiced=m.role==='assistant'?speaker(w,m.text):null;const name=m.role==='user'?state.persona.name||'나':voiced?.character?.name||(w.characters.length>1?'장면 · 내레이션':w.characters[0].name);return `<article id="demo-message-${index}" class="demo-message ${m.role}" aria-label="${m.role==='user'?'내 메시지':'샘플 답변'}"><span class="mini-label">${voiced?portrait({...w,cover:characterSource(w,voiced.character),characters:[voiced.character]},'32px'):''}${E(name)}</span>${m.role==='user'?`<p>${E(m.text)}</p>`:dialogue(voiced?.content||m.text,!w.demoLocal)}${m.role==='assistant'?button('snapshot','스냅샷','text-button message-snapshot')+button('toggle-bookmark',state.chatBookmarks.includes(index)?'북마크 해제':'북마크','text-button message-bookmark',`data-index="${index}"`):''}</article>`}
const primaryNav=[['home','작품 탐색'],['chats','나의 대화'],['works','내 작품'],['settings','내 설정'],['studio','에셋 스튜디오']];
function navActive(id){return state.view===id||id==='home'&&state.view==='detail'||id==='chats'&&state.view==='chat'||id==='works'&&state.view==='creator'}
function header(){return `<header class="topbar"><button class="header-brand" data-action="home" aria-label="온서 홈">온서 <span>ONSEO</span></button><nav class="top-navigation" aria-label="주 메뉴">${primaryNav.map(([id,label])=>button(id,E(label),navActive(id)?'active':'',`aria-current="${navActive(id)?'page':'false'}"`)).join('')}</nav><div class="top-actions"><button class="credit-pill" data-action="wallet" aria-label="테스트 지갑 열기"><span>테스트</span> ${state.balance.toLocaleString()}</button>${button('creator','＋ 작품 만들기','small-create')}</div></header><div class="demo-notice"><span>공개 목업 · 실제 AI 생성/결제 없음</span><span>작품·대화·설정은 이 탭에만 보관되며 새로고침하면 초기화됩니다.</span></div>`}
function mobileNav(){return state.view==='chat'?`<nav class="mobile-nav" aria-label="모바일 주 메뉴">${primaryNav.map(([id,label])=>button(id,E(label),navActive(id)?'active':'')).join('')}</nav>`:''}
const clone=x=>JSON.parse(JSON.stringify(x));
function stashSession(){const row=state.sessions.find(x=>x.id===state.activeSession);if(row&&state.view==='chat')Object.assign(row,{messages:clone(state.messages),tracker:clone(state.tracker),persona:clone(state.persona),draft:document.querySelector('#message-input')?.value||'',chatArt:state.chatArt,notes:state.chatNotes,memory:state.chatMemory,bookmarks:clone(state.chatBookmarks)})}
function stashDraft(){if(state.view!=='creator'||!state.creatorDraft)return;const d=state.creatorDraft;if(JSON.stringify(d)===JSON.stringify(freshDraft()))return;const id=state.editingWorkId||'local-work-'+state.nextWork++;state.editingWorkId=id;let row=state.localWorks.find(x=>x.id===id);if(!row){row={id,archived:false,preview:null};state.localWorks.unshift(row)}if(row.draft&&JSON.stringify(row.draft)!==JSON.stringify(d))row.preview=null;row.draft=clone(d);row.title=d.title.trim()||'제목 없는 작품'}
function navigate(view){stashSession();stashDraft();closeIfOpen();state.view=view;if(view!=='chat')state.persona=clone(state.savedPersona);state.collectionQuery='';history.replaceState(null,'',view==='home'?'#':'#'+view);render(true);window.scrollTo(0,0)}
function collection(kind){const isWorks=kind==='works',archived=isWorks?state.worksArchived:state.chatsArchived,records=(isWorks?state.localWorks:state.sessions).filter(r=>!!r.archived===archived&&r.title.toLowerCase().includes(state.collectionQuery.toLowerCase()));return `<main class="main" id="main" tabindex="-1"><div class="page-heading"><div><h1>${isWorks?'내 작품':'나의 대화'}</h1><p>이 탭의 ${isWorks?'제작 작품':'샘플 대화'}를 관리해요. 새로고침하면 초기화됩니다.</p></div>${isWorks?button('creator','＋ 새 작품','primary'):button('home','작품 탐색','primary')}</div><div class="workspace-tabs">${button(isWorks?'works-active':'chats-active',isWorks?'작업 중':'진행 중',!archived?'selected':'')}${button(isWorks?'works-archived':'chats-archived','보관함',archived?'selected':'')}</div><label class="search-box collection-search"><input id="collection-search" aria-label="${isWorks?'내 작품':'대화'} 검색" placeholder="이름으로 검색" value="${E(state.collectionQuery)}"></label><div class="my-work-list">${records.map(r=>`<article class="my-work">${r.preview?portrait(r.preview,'100px'):!isWorks?portrait(r.work,'100px'):'<div class="work-draft-cover">초안</div>'}<div><span class="mini-label">${isWorks?'이 탭의 작품':'샘플 대화 · '+r.messages.filter(m=>m.role==='user').length+'턴'}</span><h3>${E(r.title)}</h3><p>${E(isWorks?r.draft.hook:r.work.title)}</p></div><div class="my-work-actions">${archived?button(isWorks?'restore-work':'restore-chat','복원','secondary',`data-id="${r.id}"`):isWorks?`${button('edit-local-work','이어서 쓰기','secondary',`data-id="${r.id}"`)}${r.preview?button('open-local-work','미리보기','text-button',`data-id="${r.id}"`):''}${button('archive-work','보관','text-button',`data-id="${r.id}"`)}`:`${button('resume-chat','이어가기','secondary',`data-id="${r.id}"`)}${button('rename-chat','이름 변경','text-button',`data-id="${r.id}"`)}${button('archive-chat','보관','text-button',`data-id="${r.id}"`)}`}</div></article>`).join('')}</div>${!records.length?`<div class="collection-empty"><h2>${archived?'보관한 항목이 없어요':isWorks?'첫 번째 작품을 만들어 보세요':'아직 대화 기록이 없어요'}</h2><p>${isWorks?'작품 만들기에서 작성한 초안과 미리보기를 이곳에서 다시 열 수 있어요.':'작품을 고르고 샘플 대화를 시작하면 이곳에서 이어갈 수 있어요.'}</p>${button(isWorks?'creator':'home',isWorks?'작품 만들기':'이야기 둘러보기','primary')}</div>`:''}</main>`}
function studio(){return `<main class="main" id="main" tabindex="-1"><div class="page-heading"><div><h1>에셋 스튜디오</h1><p>캐릭터 이미지와 에셋을 확인해요.</p></div><span class="subtle-badge">공개 표지 ${works.length}개</span></div><div class="workspace-tabs">${button('studio-tab','수집 에셋',state.studioTab==='collected'?'selected':'','data-value="collected"')}${button('studio-tab','공개 표지',state.studioTab==='covers'?'selected':'','data-value="covers"')}</div>${state.studioTab==='collected'?`<div class="collection-empty"><h2>아직 수집한 에셋이 없어요</h2><p>공개 목업은 수집 보상과 비공개 이미지에 연결되지 않아요. 공개 표지 탭에서 기존 이미지를 볼 수 있어요.</p>${button('studio-tab','공개 표지 보기','primary','data-value="covers"')}</div>`:''}<div ${state.studioTab==='collected'?'hidden':''}><p class="field-help">공개 목업에는 기존 공개 표지만 표시해요. 비공개 이미지·수집 보상·AI 생성은 포함되지 않아요.</p><div class="creator-cover-grid studio-cover-grid">${works.map(w=>`<button data-action="open" data-id="${w.id}">${portrait(w,'180px')}<span>${E(w.characters[0].name)}</span></button>`).join('')}</div></div></main>`}
function settings(){const section=state.settingsSection,tab=state.libraryTab;return `<main class="main settings-hub" id="main" tabindex="-1"><div class="page-heading"><div><h1>내 설정</h1><p>페르소나, 트래커와 대화 화면을 관리해요.</p></div></div><nav class="settings-sections" aria-label="내 설정 메뉴">${[['library','설정집'],['display','대화 환경'],['assets','에셋'],['account','계정 안내']].map(([id,label])=>button('settings-section',label,section===id?'selected':'',`data-value="${id}" aria-pressed="${section===id}"`)).join('')}</nav><div class="settings-content">${section==='library'?`<div class="page-heading"><div><h2>나의 설정집</h2><p>이 탭에서 쓸 나와 장면의 형식.</p></div></div><div class="library-tabs" role="tablist" aria-label="설정집 종류">${[['personas','페르소나'],['templates','내 상태창'],['shared','공유 트래커']].map(([id,label])=>button('library-tab',label,tab===id?'selected':'',`data-value="${id}" role="tab" aria-selected="${tab===id}"`)).join('')}</div><div class="settings-panel">${tab==='personas'?`<h2>${E(state.persona.name||'내 페르소나')}</h2><p>${E(state.persona.description||'이야기 속 이름과 역할을 정해 두세요.')}</p>${button('persona',state.persona.name?'페르소나 편집':'새 페르소나','primary')}<p class="field-help">다음 대화에 사용해요. 이미 시작한 대화에는 변경이 반영되지 않아요.</p>`:tab==='templates'?`<h2>내 상태창</h2><div class="template-layout-preview">${state.layoutFields.map(label=>`<div><span>${E(label)}</span><span>미정</span></div>`).join('')}</div>${button('edit-layout','상태창 구성 편집','primary')}<p class="field-help">이 탭의 표시 이름을 바꿀 수 있어요. 실제 저장·공유 서비스와 연결되지 않아요.</p>`:`<h2>공유 트래커</h2><p>공개 목업에 포함된 예시 구성이에요. 다른 이용자의 자료를 불러오거나 내 설정을 공개하지 않아요.</p><h3>온서 기본 트래커</h3><p>장소 · 시간 · 관계 · 메모</p>${button('import-layout',state.sharedImported?'이 탭에 가져옴':'이 탭에 가져오기','secondary',state.sharedImported?'disabled':'')}`}</div>`:section==='display'?`<div class="settings-panel"><h2>대화 환경</h2><p class="field-help">화면 설정은 이 탭에만 적용돼요. 새로고침하면 초기화됩니다.</p><label class="field"><span>대화 글자 크기</span><select id="settings-font">${[16,17,19,21].map(n=>`<option value="${n}" ${n===state.font?'selected':''}>${n}px</option>`).join('')}</select></label><label class="settings-check"><input type="checkbox" id="settings-art" ${state.art?'checked':''}>캐릭터 일러스트 표시</label><p class="settings-message-preview">“다음 장면은 어디에서 시작할까요?”</p><p class="field-help">대화별 페르소나와 트래커는 대화 화면 오른쪽 위 메뉴에서 바꿀 수 있어요.</p>${button('chats','나의 대화로 이동','secondary')}</div>`:section==='assets'?`<div class="settings-panel"><h2>에셋</h2><p>이 목업의 공개 표지 이미지를 확인해요.</p>${button('studio','에셋 스튜디오로 이동','primary')}</div>`:`<div class="settings-panel"><h2>계정 안내</h2><p>공개 목업에는 실제 계정 정보가 없습니다. 작품·대화·설정은 이 탭에만 보관되며 새로고침하면 초기화됩니다.</p><p class="field-help">계정 정보 변경과 실제 결제는 아직 지원하지 않아요.</p><div class="settings-disabled"><button class="secondary" disabled>프로필 변경 · 준비 중</button><button class="secondary" disabled>계정 관리 · 준비 중</button></div></div>`}</div></main>`}
function home(){const list=editorialWorks.filter(w=>(state.audience==='전체'||w.audience===state.audience)&&(state.genre==='전체'||(state.genre==='시뮬레이션'?w.kind==='simulation':w.tag===state.genre))&&(!state.query||[w.title,w.hook,w.desc,...w.characters.map(c=>c.name),...(w.keywords||[])].join(' ').toLowerCase().includes(state.query.toLowerCase())));const f=featured()[state.feature%featured().length];return `<main class="main" id="main" tabindex="-1"><section class="featured-work" aria-roledescription="carousel" aria-label="온서 추천 이야기"><div class="featured-copy"><span class="featured-label">${E(f.tag)}</span><h1>${E(f.title)}</h1>${button('open','<span>작품 보기</span>','featured-open',`data-id="${f.id}" aria-label="${E(f.title)} 작품 보기"`)}</div><div class="featured-art"><img class="featured-backdrop" src=".${E(f.cover)}" alt="" aria-hidden="true"><img class="featured-character" src=".${E(f.cover)}" ${responsive(f,'(max-width: 600px) 340px, 600px')} alt="${E(f.characters[0].name)} 일러스트" fetchpriority="high"></div><div class="featured-controls"><div class="featured-dots" aria-label="추천 이야기 선택">${featured().map((w,i)=>button('feature','<span></span>',i===state.feature?'active':'',`data-index="${i}" aria-label="${i+1}. ${E(w.title)}" aria-pressed="${i===state.feature}"`)).join('')}</div><span class="featured-count">${String(state.feature+1).padStart(2,'0')} / 04</span>${button('previous-feature','‹','','aria-label="이전 추천 이야기"')}${button('next-feature','›','','aria-label="다음 추천 이야기"')}${button('pause',state.paused?'▷':'Ⅱ','',`aria-label="${state.paused?'추천 자동 넘김 재생':'추천 자동 넘김 일시정지'}" aria-pressed="${state.paused}" ${reduced.matches?'disabled':''}`)}</div></section><div class="discovery-heading catalog-heading"><div class="discovery-title"><h2>이야기 둘러보기</h2></div><label class="search-box"><span aria-hidden="true">⌕</span><input id="search" placeholder="작품, 캐릭터, 키워드 검색" aria-label="작품 검색" value="${E(state.query)}" autocomplete="off"></label></div><div class="discovery-controls"><div class="audience-tabs" aria-label="작품 취향">${['전체','남성향','여성향','공통'].map(x=>button('audience',x,state.audience===x?'selected':'',`data-value="${x}" aria-pressed="${state.audience===x}"`)).join('')}</div><span class="catalog-count">${list.length}개 작품</span></div><div class="genre-tabs" aria-label="장르">${['전체','시뮬레이션',...new Set(works.map(w=>w.tag))].map(x=>button('genre',x,state.genre===x?'selected':'',`data-value="${x}" aria-pressed="${state.genre===x}"`)).join('')}</div><div class="story-grid">${list.map(w=>`<button class="story-card" data-action="open" data-id="${w.id}"><div class="story-image">${portrait(w)}${rating(w)}</div><div class="story-copy"><h3>${E(w.title)}</h3><p>${E(w.hook||w.desc)}</p><div class="story-meta"><span>익명</span><span>${w.kind==='simulation'?'시뮬 · '+w.characters.length+'명':E(w.tag)}</span></div><div class="story-keywords">${(w.keywords||[]).map(k=>`<span>#${E(k)}</span>`).join('')}</div></div></button>`).join('')}</div>${!list.length?`<div class="quiet-empty"><p>검색 결과가 없어요.</p>${button('clear-search','검색 초기화','text-button')}</div>`:''}</main><footer class="site-footer"><span>온서 <span>ONSEO</span></span><span>공개 목업 · 새로고침하면 데모 상태가 초기화됩니다.</span></footer>`}
function detail(){let w=state.work;return `<main class="main" id="main" tabindex="-1"><div class="work-page">${w.demoLocal?`<div class="local-preview-notice"><div><strong>이 탭의 제작 목업</strong><p>공개 표지를 사용한 화면 미리보기예요. 게시·저장되지 않아요.</p></div>${button('edit-local-work','수정','secondary',`data-id="${w.id}"`)}</div>`:''}${button(w.demoLocal?'works':'home','‹ 작품 목록','text-button detail-back')}<section class="work-hero"><img class="work-portrait" src=".${w.cover}" ${responsive(w,'(max-width: 640px) 100px, 260px')} alt="${E(w.characters[0].name)}"><div class="work-intro"><div class="work-badges">${rating(w)}<span>${E(w.tag)}</span><span>${E(w.audience)}</span></div><h1>${E(w.title)}</h1><p class="work-hook">${E(w.hook)}</p><span class="creator-byline"><small>작가</small><strong>${E(authorLabel(w))}</strong></span><div class="work-facts"><div><strong>${w.characters.length}</strong><span>등장인물</span></div><div><strong>${w.openings.length}</strong><span>첫 장면</span></div></div><div class="work-ctas">${button('setup','새로운 대화 시작','primary')}${button('preview','첫 장면 보기')}</div><p class="field-help">${w.demoLocal?'직접 쓴 첫 장면과 정해진 샘플 답변으로 화면을 체험해요.':'작가가 준비한 시작 장면과 샘플 답변으로 화면을 체험해요.'}</p></div></section><div class="detail-tabs" role="tablist" aria-label="작품 상세">${[['info','작품 정보'],['opening','시작 상황'],['assets','캐릭터 에셋']].map(([id,label])=>button('detail-tab',label,state.detail===id?'selected':'',`role="tab" aria-selected="${state.detail===id}" data-value="${id}"`)).join('')}</div><div class="work-body"><section class="detail-content" role="tabpanel">${state.detail==='info'?`<h2>이야기의 시작</h2><p class="detail-premise">${E(w.desc)}</p><h2>세계관 · 지금의 상황</h2><div class="world-text">${prose(w.world)}</div><div class="story-keywords">${w.keywords.map(k=>`<span>#${E(k)}</span>`).join('')}</div><h2>등장인물</h2>${castPicker(w)}${w.characters.map((c,i)=>`<article class="detail-character" ${w.characters.length>1&&state.selectedCast!==i?'hidden':''}>${portrait({...w,cover:characterSource(w,c),characters:[c]},'(max-width: 640px) 62px, 82px')}<div><h3>${E(c.name)}<small>${E(characterAge(c))}</small></h3><span>${E(c.role)}</span><div class="character-prose"><h4>성격 · 관계 · 말투</h4>${prose(c.personality)}</div></div></article>`).join('')}`:state.detail==='opening'?`<h2>첫 장면 미리보기</h2><label class="opening-picker"><select id="opening" aria-label="첫 장면 선택">${w.openings.map((o,i)=>`<option value="${i}" ${i===state.opening?'selected':''}>${E(o.title)}</option>`).join('')}</select></label><div class="opening-prose">${dialogue(w.openings[state.opening].text,!w.demoLocal)}</div>${button('setup','이 장면에서 시작하기','primary')}`:`<h2>캐릭터 에셋</h2><p class="field-help">공개 표지만 볼 수 있어요. 수집 보상과 비공개 이미지는 포함되지 않아요.</p><div class="demo-public-asset">${portrait(w,'(max-width: 640px) 120px, 160px')}<div><h3>작품 표지</h3><p>${E(w.characters[0].name)}</p><span class="mini-label">공개 일러스트 · 수집 에셋 아님</span></div></div>`}</section><aside class="detail-side"><span class="mini-label">선택한 첫 장면</span><h3>${E(w.openings[state.opening].title)}</h3><p>시작 상황에서 다른 첫 만남을 고를 수 있어요.</p>${button('preview','장면 살펴보기','text-button')}<hr><span class="mini-label">제작</span><h3>${E(authorLabel(w))}</h3><p>${w.demoLocal?'입력한 내용은 이 탭의 제작 미리보기에만 표시돼요.':'가상 인물과 오리지널 이야기입니다.'}</p></aside></div></div></main>`}
function chat(){const w=state.work;return `<main class="chat-main" id="main" tabindex="-1"><div class="demo-chat-layout ${!state.art?'art-hidden':''}"><aside class="chat-art"><div class="chat-art-stage"><img class="chat-art-image" src=".${E(chatArtSource(w))}" ${responsive({...w,cover:chatArtSource(w)},'(max-width: 640px) 1px, (max-width: 900px) 36vw, 42vw')} alt="${E(w.characters[0].name)} 일러스트"><div class="chat-art-caption"><span>${E(w.title)}</span><strong>${E(chatArtCharacter(w)?.name||(w.characters.length>1?w.title:w.characters[0].name))}</strong></div>${w.characters.length>1?`<label class="chat-art-select"><span>표시할 이미지</span><select id="chat-character-image" aria-label="대화 옆 이미지 선택"><option value="cover">작품 표지</option>${w.characters.map(c=>`<option value="cast:${E(c.id)}" ${state.chatArt==='cast:'+c.id?'selected':''}>${E(c.name)} · 공개 캐릭터</option>`).join('')}</select></label>`:''}<details class="chat-art-details"><summary>작품 정보 <span>＋</span></summary><div><h2>${E(w.title)}</h2><p>${E(w.desc)}</p></div></details></div></aside><section class="demo-conversation"><header class="demo-chat-header">${button('back-detail','‹','icon-button','aria-label="작품 정보로 돌아가기"')}<div><strong>${E(w.characters.length>1?w.title:w.characters[0].name)}</strong><span>${E(w.openings[state.opening].title)}</span></div><div class="chat-header-tools">${button('assets','Assets','assets-button')}${button('menu','☰','icon-button chat-menu-button','aria-label="대화 메뉴 열기"')}</div></header><div class="sample-label">샘플 대화 · AI가 생성한 답변이 아니에요</div><div class="demo-messages" id="messages">${state.messages.map((m,i)=>messageMarkup(m,w,i)).join('')}</div><div class="demo-suggestions">${w.openings[state.opening].suggestions.map(x=>button('suggest',E(x),'suggestion',`data-text="${E(x)}"`)).join('')}</div><form id="message-form" class="demo-composer"><textarea id="message-input" rows="2" maxlength="1000" aria-label="샘플 대화 메시지" placeholder="메시지를 입력해 화면을 체험해 보세요" required></textarea><button class="primary" type="submit">보내기</button></form><p class="composer-note">직접 입력한 내용도 전송·저장되지 않아요. 정해진 샘플 답변이 이어집니다.</p></section></div></main>`}
function render(focus=false){app.classList.toggle('chat-view',state.view==='chat');app.innerHTML=header()+(state.view==='home'?home():state.view==='creator'?creator():state.view==='detail'?detail():state.view==='works'?collection('works'):state.view==='chats'?collection('chats'):state.view==='settings'?settings():state.view==='studio'?studio():chat())+mobileNav();document.title=['works','chats','settings','studio'].includes(state.view)?primaryNav.find(x=>x[0]===state.view)[1]+' · 온서 목업':state.view==='creator'?'작품 만들기 · 온서 목업':state.work?.demoLocal?'이 탭의 제작 목업 · 온서':state.work&&state.view!=='home'?`${state.work.title} · 온서 목업`:'온서 ONSEO · 공개 목업';document.documentElement.style.setProperty('--demo-message-size',state.font+'px');if(focus)document.querySelector('#main')?.focus({preventScroll:true});if(state.view==='chat'){let el=document.querySelector('#messages');el.scrollTop=el.scrollHeight;const saved=state.sessions.find(x=>x.id===state.activeSession);if(saved?.draft)document.querySelector('#message-input').value=saved.draft}}
let previousFocus;
function modal(title,content,wide=false){if(!dialog.open)previousFocus=document.activeElement;dialog.className='demo-dialog'+(wide?' wide':'');dialog.innerHTML=`<header><h2 id="dialog-title">${E(title)}</h2>${button('close','×','icon-button','aria-label="닫기"')}</header><div class="dialog-body">${content}</div>`;if(!dialog.open)dialog.showModal();(dialog.querySelector('.dialog-body input:not([type="hidden"]):not([disabled]), .dialog-body select:not([disabled]), .dialog-body textarea:not([disabled]), .dialog-body button:not([disabled])')||dialog.querySelector('button'))?.focus();dialog.scrollTop=0;dialog.querySelector('.dialog-body').scrollTop=0}
function close(){dialog.close();dialog.innerHTML='';if(previousFocus?.isConnected)previousFocus.focus();else if(previousFocus?.dataset?.action)focusAction(previousFocus.dataset.action);else document.querySelector('#main')?.focus({preventScroll:true})}
function focusAction(action,value){document.querySelector(`[data-action="${action}"]${value?'[data-value="'+value+'"]':''}`)?.focus({preventScroll:true})}
function personaFields(){return `<p class="field-help">이 탭에서 체험할 가상 인물을 정해 주세요. 개인정보는 넣지 않는 것이 좋아요.</p><div class="demo-fields"><label>이름<input id="persona-name" maxlength="30" placeholder="이야기 속 나의 이름" value="${E(state.persona.name)}"></label><label>역할<input id="persona-role" maxlength="80" placeholder="예: 기록을 좋아하는 여행자" value="${E(state.persona.role)}"></label><label>소개<textarea id="persona-description" maxlength="500" rows="3" placeholder="말투, 성격, 관계를 적어 주세요">${E(state.persona.description)}</textarea></label></div>`}
function setup(){const w=state.work;modal('새로운 대화 시작',`<p class="setup-work">${E(w.title)}</p><label class="demo-label">시작 상황<select id="setup-opening">${w.openings.map((o,i)=>`<option value="${i}" ${i===state.opening?'selected':''}>${E(o.title)}</option>`).join('')}</select></label><section class="demo-persona-inline"><div class="dialog-section-heading"><h3>내 페르소나</h3>${button('toggle-persona','＋ 페르소나 추가','secondary')}</div><div id="setup-persona-summary">${state.persona.name?`<strong>${E(state.persona.name)}</strong><p>${E(state.persona.role)}</p>`:'이야기 속 나를 먼저 설정할 수 있어요.'}</div><div id="setup-persona-fields" hidden>${personaFields()}</div></section><div class="demo-start-preview"><h3>첫 장면</h3><div id="setup-preview">${dialogue(w.openings[state.opening].text,!w.demoLocal)}</div></div><p class="field-help">샘플 대화를 열며, 실제 AI 호출이나 잉크 차감은 없어요.</p><div class="dialog-actions">${button('close','취소')}${button('start-chat','샘플 대화 시작','primary')}</div>`,true)}
function savePersona(){const name=dialog.querySelector('#persona-name');if(name){state.persona={name:name.value.trim(),role:dialog.querySelector('#persona-role').value.trim(),description:dialog.querySelector('#persona-description').value.trim()};if(state.view!=='chat')state.savedPersona=clone(state.persona)}}
function startChat(){stashSession();savePersona();state.opening=Number(dialog.querySelector('#setup-opening')?.value??state.opening);state.view='chat';state.chatArt='cover';state.chatNotes='';state.chatMemory='';state.chatBookmarks=[];state.tracker={place:'첫 만남의 장소',time:'이야기의 시작',relationship:'첫 만남',memo:''};state.messages=[{role:'assistant',text:state.work.openings[state.opening].text}];state.work=clone(state.work);state.activeSession='local-chat-'+state.nextSession++;state.sessions.unshift({id:state.activeSession,title:state.work.title,work:clone(state.work),opening:state.opening,messages:clone(state.messages),persona:clone(state.persona),tracker:clone(state.tracker),archived:false,draft:'',layoutFields:clone(state.layoutFields)});history.replaceState(null,'','#chat/'+state.activeSession);close();render(true);window.scrollTo(0,0)}
function send(text){if(!text.trim())return;const active=state.sessions.find(x=>x.id===state.activeSession);if(active)active.draft='';state.messages.push({role:'user',text:text.trim()});const replies=state.work.sampleReplies,turns=state.work.sampleTurns?.filter(t=>state.work.characters.some(c=>c.id===t.characterId));const n=Math.floor(state.messages.filter(m=>m.role==='user').length-1);state.messages.push({role:'assistant',text:turns?.length?turnText(state.work,turns[n%turns.length]):replies[n%replies.length]||'“이 장면의 다음 대화는 준비 중이에요.”'});render();stashSession();document.querySelector('#message-input')?.focus()}
function wallet(){modal('테스트 지갑',`<div class="wallet-balance"><span>체험용 테스트 잉크</span><strong>${state.balance.toLocaleString()} <small>잉크</small></strong></div><p class="field-help">실제 돈이나 유료 잉크이 아니에요. 카드 정보와 계정은 필요하지 않아요.</p><h3>테스트 충전</h3><div class="demo-packages">${[120,360,900].map(n=>button('checkout',`<strong>${n.toLocaleString()} 잉크</strong><span>실제 청구 ₩0</span>`,'demo-package',`data-amount="${n}"`)).join('')}</div><h3>이 탭의 테스트 내역</h3>${state.transactions.length?`<ul class="demo-ledger">${state.transactions.map(t=>`<li><span>데모 충전</span><strong>＋${t.amount.toLocaleString()} 잉크</strong><span>실제 청구 ₩0</span></li>`).join('')}</ul>`:'<p class="field-help">아직 테스트한 충전이 없어요.</p>'}<div class="dialog-actions">${button('close','닫기')}</div>`)}
function checkout(amount){modal('테스트 결제 확인',`<p class="demo-receipt-label">가상 결제 화면 · 실제 영수증이 아닙니다</p><dl class="demo-checkout"><div><dt>제공</dt><dd>온서 공개 목업</dd></div><div><dt>체험 항목</dt><dd>테스트 잉크 ${amount.toLocaleString()} 잉크</dd></div><div><dt>실제 청구 금액</dt><dd>₩0</dd></div><div><dt>결제 수단</dt><dd>데모 시뮬레이션</dd></div><div><dt>유지 기간</dt><dd>이 탭을 새로고침할 때까지</dd></div></dl><p class="field-help">구매·구독·자동 갱신이 없고, 실제 결제 수단에 연결되지 않아요.</p><label class="demo-check"><input id="test-consent" type="checkbox">실제 결제 없는 테스트 충전임을 확인했어요</label><div class="dialog-actions">${button('wallet','취소')}${button('complete-checkout','₩0 테스트 충전 완료','primary',`data-amount="${amount}" disabled`)}</div>`)}
function tracker(){const labels=state.sessions.find(x=>x.id===state.activeSession)?.layoutFields||state.layoutFields;modal('트래커',`<p class="field-help">이 대화의 상태를 직접 바꿔 보는 데모예요. AI가 자동으로 추적하지 않아요.</p><div class="demo-fields">${[['place','장소'],['time','시간'],['relationship','관계']].map(([key,label],i)=>`<label>${E(labels[i]||label)}<input id="tracker-${key}" maxlength="80" value="${E(state.tracker[key])}"></label>`).join('')}<label>${E(labels[3]||'메모')}<textarea id="tracker-memo" rows="3" maxlength="400">${E(state.tracker.memo)}</textarea></label></div><div class="dialog-actions">${button('close','취소')}${button('save-tracker','이 탭에 적용','primary')}</div>`)}
function menu(){const w=state.work,row=state.sessions.find(r=>r.id===state.activeSession);modal('대화 설정',`<div class="reference-settings-menu"><div class="drawer-wallet"><span>테스트 잉크 ${state.balance}</span>${button('wallet','내역','')}${button('wallet','테스트 충전','')}</div><section class="drawer-room"><h3>채팅방 이름</h3>${button('rename-chat',`<strong>${E(row?.title||w.title)}</strong><span>✎</span>`,'drawer-room-name',`data-id="${E(state.activeSession)}"`)}</section><section class="drawer-album"><button class="drawer-section-link" data-action="assets"><strong>앨범</strong><span>›</span></button><div class="drawer-album-strip">${w.characters.map(c=>button('assets',portrait({...w,cover:characterSource(w,c),characters:[c]},'100px'),'','aria-label="'+E(c.name)+' 앨범 보기"')).join('')}</div></section><section class="drawer-model"><h3>선택된 모델</h3><select aria-label="선택된 모델" disabled><option>샘플 대화 · 실제 AI 연결 전</option></select><label class="drawer-disabled-toggle"><span>크리에이터 추천 모델 사용</span><input type="checkbox" disabled></label><button class="drawer-row" disabled><span>모델 설정 <small>AI 연결 후 사용</small></span><span>›</span></button></section><section><h3 class="drawer-group-title">정보 수정</h3><nav aria-label="정보 수정">${button('persona','<span>페르소나</span><span>›</span>','drawer-row')}${button('notes-memory','<span>유저 노트</span><span>›</span>','drawer-row')}</nav></section><section><h3 class="drawer-group-title">채팅방 설정</h3><nav aria-label="채팅방 설정">${button('display','<span>맞춤 채팅방</span><span>›</span>','drawer-row')}<button class="drawer-row" disabled><span>목소리 <small>준비 중</small></span><span>›</span></button>${button('bookmarks','<span>북마크</span><span>›</span>','drawer-row')}</nav></section></div>`);dialog.classList.add('chat-settings-drawer');dialog.scrollTop=0;dialog.querySelector('.dialog-body').scrollTop=0}
const creatorSteps=['작품 소개','세계관 · 비밀','등장인물','첫 장면','표지 · 완성','응답 규칙','트래커','캐릭터 에셋'];
const draftLimits={title:80,hook:80,world:2400,name:40,age:3,role:100,personality:1200,openingTitle:80,openingText:2400,replyStyle:300,replyInstructions:1200,trackerLabels:160,assetNote:300};
const freshDraft=()=>({title:'',hook:'',world:'',name:'',age:'25',role:'',personality:'',openingTitle:'',openingText:'',replyStyle:'',replyLength:'균형 있게',replyInstructions:'',trackerLabels:'장소, 시간, 관계, 메모',assetNote:'',tag:'일상',rating:'19+',cover:''});
const authorLabel=w=>w.demoLocal?'나':w.author;
function draftField(key,label,placeholder,rows=0){const value=state.creatorDraft[key]??'';const props=`id="draft-${key}" data-draft="${key}" maxlength="${draftLimits[key]}" placeholder="${E(placeholder)}"`;return `<label class="field"><span>${E(label)}</span>${rows?`<textarea ${props} rows="${rows}">${E(value)}</textarea>`:`<input ${props} value="${E(value)}" ${key==='age'?'type="number" min="19" max="999"':''}>`}<small><span id="draft-count-${key}">${String(value).length}</span>/${draftLimits[key]}</small></label>`}
function creator(){const d=state.creatorDraft,step=state.creatorStep;const chosen=works.find(w=>w.cover===d.cover);return `<main class="main creator-main" id="main" tabindex="-1"><div class="editor-heading">${button('cancel-creator','‹ 돌아가기','text-button')}<div><span class="save-note">이 탭의 제작 목업</span>${button('save-local-draft','이 탭에 보관','secondary')}${button('preview-draft','미리보기','primary')}</div></div><div class="editor-title"><h1>${state.createdWork?'작품 편집':'새 작품'}</h1><p class="field-help">입력한 내용은 이 탭에서만 유지돼요. 공개 게시나 AI 생성은 하지 않아요.</p></div><div class="editor-layout demo-editor-layout"><nav class="step-tabs" aria-label="작품 제작 단계">${creatorSteps.map((name,i)=>button('creator-step',`<span>${String(i+1).padStart(2,'0')}</span>${name}`,step===i?'active':'',`data-index="${i}" aria-current="${step===i?'step':'false'}"`)).join('')}</nav><section class="editor-content"><div class="form-panel"><div class="form-section-title"><span>${String(step+1).padStart(2,'0')}</span><div><h2>${creatorSteps[step]}</h2><p>${['제목과 목록에 보일 짧은 소개를 정해 주세요.','독자가 처음 알게 될 이야기의 배경을 적어 주세요.','가상 인물 한 명의 역할과 말투를 정해 주세요.','대화가 시작되는 장면을 직접 적어 주세요.','공개 목업 이미지를 골라 제작 화면을 미리 보세요.','답변 문체와 진행 방식을 적어 주세요.','대화에 표시할 상태 항목을 정해 주세요.','공개 표지와 에셋 화면을 확인해 주세요.'][step]}</p></div></div>${state.creatorError?`<p class="creator-error" role="alert">${E(state.creatorError)}</p>`:''}${step===0?`${draftField('title','작품 제목 *','이야기의 이름을 지어 주세요')}${draftField('hook','목록에 보일 한 줄 소개 *','누구와 무엇을 할지 짧게 써 주세요',2)}<label class="field"><span>이용 등급</span><select id="draft-rating" data-draft="rating"><option value="19+" ${d.rating==='19+'?'selected':''}>19세 이상</option><option value="all" ${d.rating==='all'?'selected':''}>전체 이용가</option></select></label><label class="field"><span>장르</span><select id="draft-tag" data-draft="tag">${[...new Set(works.map(w=>w.tag))].map(tag=>`<option ${d.tag===tag?'selected':''}>${E(tag)}</option>`).join('')}</select></label><p class="field-help">이 제작 목업은 비노골적인 성인 캐릭터 이야기를 전제로 해요. 등급·신원 인증 기능은 포함되지 않아요.</p>`:step===1?`${draftField('world','세계관 · 지금의 상황 *','장소, 사건, 인물과 독자의 관계를 적어 주세요',8)}<p class="field-help">실제 개인정보나 비공개 제작 자료를 넣지 않아도 화면을 체험할 수 있어요.</p>`:step===2?`<div class="form-row">${draftField('name','캐릭터 이름 *','가상 인물 이름')}${draftField('age','나이 *','19세 이상')}</div>${draftField('role','역할','이야기 속 역할')}${draftField('personality','성격과 말투','성격, 말투, 독자와의 관계',5)}<details class="creator-optional"><summary>응답 스타일 · 선택</summary>${draftField('replyStyle','말투와 표현','예: 짧고 차분한 문장',3)}<label class="field"><span>응답 길이</span><select data-draft="replyLength" id="draft-replyLength">${['짧게','균형 있게','길게'].map(v=>`<option ${d.replyLength===v?'selected':''}>${v}</option>`).join('')}</select></label><p class="field-help">화면 설정만 체험해요. 실제 AI 답변에 적용되지는 않아요.</p></details>`:step===3?`${draftField('openingTitle','첫 장면 제목 *','첫 만남의 이름')}${draftField('openingText','시작 장면 *','직접 쓴 대사와 장면을 넣어 주세요. 행동 묘사는 *별표*로 감쌀 수 있어요.',9)}<p class="field-help">작성한 첫 장면 그대로 샘플 대화 화면을 확인할 수 있어요.</p>`:step===4?`<p class="field-help">아래 이미지는 공개 목업의 기존 표지예요. 새 이미지를 업로드하거나 생성하지 않아요.</p><div class="creator-cover-grid" aria-label="공개 표지 선택">${works.map(w=>`<button type="button" data-action="creator-cover" data-id="${w.id}" class="${d.cover===w.cover?'selected':''}" aria-pressed="${d.cover===w.cover}" aria-label="${E(w.characters[0].name)} 공개 표지 선택">${portrait(w,'96px')}<span>${E(w.characters[0].name)}</span></button>`).join('')}</div><p class="field-help">미리보기는 이 탭에서만 볼 수 있고, 작품 목록에 게시되지 않아요.</p>`:extraCreatorStep(step)}<div class="creator-step-actions">${step>0?button('creator-previous','이전'):''}${step<7?button('creator-next','다음','primary'):button('preview-draft','제작 목업 미리보기','primary')}</div></div></section><aside class="editor-preview demo-editor-preview"><span class="mini-label">이 탭의 미리보기</span>${chosen?portrait(chosen,'180px'):'<div class="creator-empty-cover">표지를 선택해 주세요</div>'}<h3 id="draft-preview-title">${E(d.title||'작품 제목')}</h3><p id="draft-preview-hook">${E(d.hook||'한 줄 소개')}</p><span>공개 게시 없음 · 새로고침 시 초기화</span>${state.createdWork?button('show-created','이전 미리보기 보기','text-button'):''}</aside></div></main>`}
function extraCreatorStep(step){return step===5?`${draftField('replyStyle','문체 · 표현 규칙','예: 차분하고 간결한 대사',3)}${draftField('replyInstructions','대화 진행 지침','예: 사용자의 대사와 행동을 대신 결정하지 않기',5)}<p class="field-help">입력한 규칙은 이 탭의 제작 초안에만 보관돼요. 정해진 샘플 답변에는 적용되지 않아요.</p>`:step===6?`${draftField('trackerLabels','상태 항목','장소, 시간, 관계, 메모',3)}<p class="field-help">쉼표로 구분한 항목을 제작 초안에서 확인할 수 있어요. 실제 상태 추적과 제작자 트래커 저장 서비스는 연결되지 않았어요.</p>`:`<h3>캐릭터 에셋</h3><p class="field-help">선택한 공개 표지가 대화 일러스트로 표시돼요. 추가 업로드·비공개 보상·이미지 생성은 연결되지 않았어요.</p>${state.creatorDraft.cover?portrait(works.find(w=>w.cover===state.creatorDraft.cover),'180px'):'<p>표지 · 완성에서 공개 표지를 선택해 주세요.</p>'}${draftField('assetNote','에셋 메모','표지에 관한 메모',3)}<button type="button" class="secondary" disabled>추가 에셋 업로드 · 준비 중</button>`}
function beginCreator(){if(state.view==='creator')return;stashSession();closeIfOpen();state.creatorReturn={view:state.view,work:state.work,opening:state.opening,detail:state.detail};state.editingWorkId=null;state.creatorDraft=freshDraft();state.createdDraft=null;state.createdWork=null;state.creatorStep=0;state.creatorError='';state.view='creator';render(true);window.scrollTo(0,0)}
function changeDraft(key,value){if(!state.creatorDraft)return;if(Object.hasOwn(draftLimits,key))state.creatorDraft[key]=String(value).slice(0,draftLimits[key]);else if(key==='rating'&&['19+','all'].includes(value))state.creatorDraft.rating=value;else if(key==='tag'&&works.some(w=>w.tag===value))state.creatorDraft.tag=value;else if(key==='replyLength'&&['짧게','균형 있게','길게'].includes(value))state.creatorDraft.replyLength=value;else return;const count=document.querySelector('#draft-count-'+key);if(count)count.textContent=String(state.creatorDraft[key]).length;const preview=document.querySelector('#draft-preview-'+key);if(preview)preview.textContent=state.creatorDraft[key]||(key==='title'?'작품 제목':'한 줄 소개')}
function previewDraft(){const d=state.creatorDraft;const required=[['title',0,'작품 제목을 적어 주세요.'],['hook',0,'한 줄 소개를 적어 주세요.'],['world',1,'세계관을 적어 주세요.'],['name',2,'가상 캐릭터 이름을 적어 주세요.'],['openingTitle',3,'첫 장면 제목을 적어 주세요.'],['openingText',3,'시작 장면을 적어 주세요.']];let invalid=required.find(([key])=>!d[key].trim());if(!invalid&&(!Number.isInteger(Number(d.age))||Number(d.age)<19||Number(d.age)>999))invalid=['age',2,'캐릭터 나이는 19~999 사이의 정수로 적어 주세요.'];if(!invalid&&!works.some(w=>w.cover===d.cover))invalid=['cover',4,'공개 표지 하나를 골라 주세요.'];if(invalid){state.creatorStep=invalid[1];state.creatorError=invalid[2];render(true);document.querySelector('#draft-'+invalid[0])?.focus();return false}state.createdDraft={...d};state.createdWork={id:state.editingWorkId||'local-work-'+state.nextWork++,demoLocal:true,title:d.title.trim(),hook:d.hook.trim(),tag:d.tag,desc:d.hook.trim(),world:d.world.trim(),audience:'이 탭의 제작 목업',keywords:[],cover:d.cover,author:'나',rating:d.cover.endsWith('character-01.webp')||d.cover.endsWith('character-27.svg')?'all':d.rating,characters:[{name:d.name.trim(),age:Number(d.age),role:d.role.trim(),personality:d.personality.trim()}],openings:[{title:d.openingTitle.trim(),text:d.openingText.trim(),suggestions:['첫 장면을 이어서 살펴볼게요.']}],sampleReplies:['“지금은 제작 화면을 확인하는 샘플 답변이에요. 실제 AI가 이야기를 생성하지는 않아요.”']};state.editingWorkId=state.createdWork.id;let row=state.localWorks.find(x=>x.id===state.editingWorkId);if(!row){row={id:state.editingWorkId,archived:false};state.localWorks.unshift(row)}Object.assign(row,{draft:clone(d),title:d.title.trim(),preview:clone(state.createdWork)});showCreated();return true}
function showCreated(){if(!state.createdWork)return;stashDraft();closeIfOpen();state.work=state.createdWork;state.selectedCast=0;state.view='detail';state.opening=0;state.detail='info';state.creatorError='';history.replaceState(null,'','#local-work/'+state.createdWork.id);render(true);window.scrollTo(0,0)}

const actions={'toggle-bookmark'(el){const index=Number(el.dataset.index);state.chatBookmarks=state.chatBookmarks.includes(index)?state.chatBookmarks.filter(i=>i!==index):[...state.chatBookmarks,index];stashSession();render()},bookmarks(){modal('북마크',`<p class="field-help">이 대화에서 표시한 장면이에요. 이 탭에서만 보관돼요.</p>${state.chatBookmarks.length?state.chatBookmarks.map(i=>button('jump-bookmark',E(state.messages[i]?.text?.slice(0,130)||'장면'),'menu-row',`data-index="${i}"`)).join(''):'<p>아직 북마크한 장면이 없어요. 답변 아래 북마크를 눌러 표시할 수 있어요.</p>'}<div class="dialog-actions">${button('menu','돌아가기')}</div>`)},'jump-bookmark'(el){close();document.querySelector('#demo-message-'+el.dataset.index)?.scrollIntoView({block:'center'})},'notes-memory'(){modal('유저 노트',`<p class="field-help">이 탭의 대화에만 보관돼요. 실제 AI 응답에는 적용되지 않아요.</p><label class="field"><span>유저 노트</span><textarea id="chat-notes" maxlength="3000" rows="4">${E(state.chatNotes)}</textarea></label><details class="drawer-advanced"><summary>장기 기억</summary><label class="field"><span>기억할 내용</span><textarea id="chat-memory" maxlength="6000" rows="4">${E(state.chatMemory)}</textarea></label></details><div class="dialog-actions">${button('menu','돌아가기')}${button('save-chat-notes','이 탭에 적용','primary')}</div>`)},'save-chat-notes'(){state.chatNotes=dialog.querySelector('#chat-notes').value;state.chatMemory=dialog.querySelector('#chat-memory').value;stashSession();close();notify('이 대화의 노트와 기억을 이 탭에 보관했어요.')},'conversation-manage'(){modal('대화 관리',`<nav class="demo-menu">${button('chats','나의 대화로 이동','menu-row')}${button('restart','샘플 대화 다시 시작','menu-row')}${button('back-detail','작품 정보로 돌아가기','menu-row')}</nav><p class="field-help">현재 대화는 이 탭에서만 이어갈 수 있어요.</p><div class="dialog-actions">${button('menu','돌아가기')}</div>`)},'select-cast'(el){state.selectedCast=Number(el.dataset.index);render()},'select-cast-art'(el){state.chatArt=el.dataset.value;close();render()},'studio-tab'(el){state.studioTab=el.dataset.value;render()},works(){navigate('works')},chats(){navigate('chats')},settings(){navigate('settings')},studio(){navigate('studio')},'works-active'(){state.worksArchived=false;navigate('works')},'works-archived'(){state.worksArchived=true;navigate('works')},'chats-active'(){state.chatsArchived=false;navigate('chats')},'chats-archived'(){state.chatsArchived=true;navigate('chats')},'archive-work'(el){const r=state.localWorks.find(x=>x.id===el.dataset.id);if(r)r.archived=true;render()},'restore-work'(el){const r=state.localWorks.find(x=>x.id===el.dataset.id);if(r)r.archived=false;render()},'archive-chat'(el){const r=state.sessions.find(x=>x.id===el.dataset.id);if(r)r.archived=true;render()},'restore-chat'(el){const r=state.sessions.find(x=>x.id===el.dataset.id);if(r)r.archived=false;render()},'edit-local-work'(el){const r=state.localWorks.find(x=>x.id===el.dataset.id);if(!r)return;stashSession();state.creatorReturn={view:'works'};state.editingWorkId=r.id;state.creatorDraft=clone(r.draft);state.createdDraft=clone(r.draft);state.createdWork=r.preview?clone(r.preview):null;state.creatorStep=0;state.creatorError='';state.view='creator';render(true)},'open-local-work'(el){const r=state.localWorks.find(x=>x.id===el.dataset.id);if(!r?.preview)return;state.createdWork=clone(r.preview);state.createdDraft=clone(r.draft);state.editingWorkId=r.id;showCreated()},'save-local-draft'(){stashDraft();if(state.editingWorkId){navigate('works');notify('초안을 이 탭의 내 작품에 보관했어요.')}else notify('작품 제목이나 내용을 먼저 입력해 주세요.')},'resume-chat'(el){stashSession();const r=state.sessions.find(x=>x.id===el.dataset.id);if(!r)return;state.activeSession=r.id;state.work=clone(r.work);state.opening=r.opening;state.messages=clone(r.messages);state.persona=clone(r.persona);state.tracker=clone(r.tracker);state.chatArt=r.chatArt||'cover';state.chatNotes=r.notes||'';state.chatMemory=r.memory||'';state.chatBookmarks=clone(r.bookmarks||[]);state.view='chat';history.replaceState(null,'','#chat/'+r.id);render(true)},'rename-chat'(el){const r=state.sessions.find(x=>x.id===el.dataset.id);if(!r)return;modal('대화 이름 변경',`<label class="field"><span>대화 이름</span><input id="rename-chat-title" maxlength="80" value="${E(r.title)}"></label><div class="dialog-actions">${button('close','취소')}${button('save-chat-title','이 탭에 적용','primary',`data-id="${r.id}"`)}</div>`)},'save-chat-title'(el){const r=state.sessions.find(x=>x.id===el.dataset.id),value=dialog.querySelector('#rename-chat-title').value.trim();if(r&&value)r.title=value;close();render()},'settings-section'(el){state.settingsSection=el.dataset.value;render()},'library-tab'(el){state.libraryTab=el.dataset.value;render()},'edit-layout'(){modal('상태창 구성 편집',`${state.layoutFields.map((name,i)=>`<label class="field"><span>항목 ${i+1}</span><input id="layout-${i}" maxlength="30" value="${E(name)}"></label>`).join('')}<div class="dialog-actions">${button('close','취소')}${button('save-layout','이 탭에 적용','primary')}</div>`)},'save-layout'(){state.layoutFields=state.layoutFields.map((v,i)=>dialog.querySelector('#layout-'+i).value.trim()||v);close();render()},'import-layout'(){state.layoutFields=['장소','시간','관계','메모'];state.sharedImported=true;render()},creator:beginCreator,'creator-step'(el){state.creatorStep=Number(el.dataset.index);state.creatorError='';render(true)},'creator-next'(){state.creatorStep=Math.min(7,state.creatorStep+1);state.creatorError='';render(true)},'creator-previous'(){state.creatorStep=Math.max(0,state.creatorStep-1);state.creatorError='';render(true)},'creator-cover'(el){const work=works.find(w=>w.id===el.dataset.id);if(!work)return;state.creatorDraft.cover=work.cover;if(work.rating==='all')state.creatorDraft.rating='all';state.creatorError='';render();document.querySelector(`[data-action="creator-cover"][data-id="${work.id}"]`)?.focus()},'preview-draft':previewDraft,'show-created':showCreated,'cancel-creator'(){stashDraft();const prior=state.creatorReturn;state.creatorDraft=null;state.creatorError='';if(prior&&prior.view!=='creator'){state.view=prior.view;state.work=prior.work;state.opening=prior.opening;state.detail=prior.detail;render(true)}else actions.home()},home(){navigate('home')},open(el){openWork(el.dataset.id)},audience(el){state.audience=el.dataset.value;render();focusAction('audience',state.audience)},genre(el){state.genre=el.dataset.value;render();focusAction('genre',state.genre)},'clear-search'(){state.query='';state.genre='전체';state.audience='전체';render()},feature(el){state.feature=Number(el.dataset.index);render();document.querySelector(`[data-action="feature"][data-index="${state.feature}"]`)?.focus()},'previous-feature'(){state.feature=(state.feature+featured().length-1)%featured().length;render();focusAction('previous-feature')},'next-feature'(){state.feature=(state.feature+1)%featured().length;render();focusAction('next-feature')},pause(){state.paused=!state.paused;render();focusAction('pause')},'detail-tab'(el){state.detail=el.dataset.value;render();document.querySelector(`[data-action="detail-tab"][data-value="${state.detail}"]`)?.focus()},preview(){state.detail='opening';render();document.querySelector('.detail-tabs')?.scrollIntoView({block:'start',behavior:'smooth'})},setup,close,persona(){modal('내 페르소나',`${personaFields()}<div class="dialog-actions">${button('close','취소')}${button('save-persona','이 탭에 적용','primary')}</div>`)},'save-persona'(){savePersona();if(state.view==='chat')stashSession();close();render();notify('페르소나를 이 탭에 적용했어요.')},'toggle-persona'(){const fields=dialog.querySelector('#setup-persona-fields');fields.hidden=!fields.hidden;if(!fields.hidden)fields.querySelector('input').focus()},'start-chat':startChat,'back-detail'(){stashSession();closeIfOpen();state.persona=clone(state.savedPersona);state.view='detail';history.replaceState(null,'',state.work.demoLocal?'#local-work/'+state.work.id:'#work/'+encodeURIComponent(state.work.id));render(true)},suggest(el){send(el.dataset.text)},assets(){if(state.work.characters.length>1){modal('Assets',`<p class="field-help">공개 캐릭터 이미지만 표시해요. 선택은 대화 옆 이미지에만 적용됩니다.</p><div class="cast-asset-grid">${state.work.characters.map(c=>button('select-cast-art',`${portrait({...state.work,cover:characterSource(state.work,c),characters:[c]},'180px')}<strong>${E(c.name)}</strong>`,'',`data-value="cast:${E(c.id)}"`)).join('')}</div>`);return}modal('Assets',`<p class="field-help">공개 표지 일러스트만 표시됩니다.</p><div class="demo-public-asset">${portrait(state.work,'(max-width: 640px) 120px, 160px')}<div><h3>${E(state.work.characters[0].name)}</h3><p>작품 표지</p><span class="mini-label">선택된 이미지</span></div></div><p class="field-help">수집 에셋과 비공개 보상은 이 목업에 포함되지 않아요.</p><div class="dialog-actions">${button('close','닫기')}</div>`)},menu,tracker,'save-tracker'(){for(const k of ['place','time','relationship','memo'])state.tracker[k]=dialog.querySelector('#tracker-'+k).value.trim();stashSession();close();notify('트래커를 이 탭에 적용했어요.')},snapshot(){modal('스냅샷',`<div class="snapshot-confirmation"><span class="snapshot-confirmation-icon">▣</span><h3>이 장면을 이미지로 생성하시겠습니까?</h3><p>이미지 생성 기능은 아직 준비 중이에요.</p><div class="snapshot-confirmation-actions">${button('close','취소')}${button('unavailable','생성','primary','disabled aria-label="스냅샷 생성 · 준비 중"')}</div></div>`)},wallet,checkout(el){checkout(Number(el.dataset.amount))},'complete-checkout'(el){if(!dialog.querySelector('#test-consent')?.checked)return;const amount=Number(el.dataset.amount);if(![120,360,900].includes(amount))return;state.balance+=amount;state.transactions.unshift({amount});render();modal('테스트 충전 완료',`<div class="demo-success"><span aria-hidden="true">✓</span><h3>${amount.toLocaleString()} 잉크가 반영됐어요.</h3><p>실제 청구 ₩0 · 가상 결과이며 영수증이 아닙니다.</p></div><div class="dialog-actions">${button('wallet','테스트 지갑 보기','primary')}${button('close','닫기')}</div>`)},display(){modal('맞춤 채팅방',`<label class="demo-label">대화 글자 크기<select id="font-size">${[16,17,19,21].map(n=>`<option value="${n}" ${n===state.font?'selected':''}>${n}px</option>`).join('')}</select></label><label class="demo-check"><input id="show-art" type="checkbox" ${state.art?'checked':''}>캐릭터 일러스트 표시</label><div class="dialog-actions">${button('close','취소')}${button('save-display','적용','primary')}</div>`)},'save-display'(){state.font=Number(dialog.querySelector('#font-size').value);state.art=dialog.querySelector('#show-art').checked;close();render()},restart(){modal('샘플 대화를 다시 시작할까요?',`<p>이 탭에 입력한 대화가 초기화됩니다.</p><div class="dialog-actions">${button('close','취소')}${button('confirm-restart','다시 시작','primary')}</div>`)},'confirm-restart'(){state.chatBookmarks=[];state.messages=[{role:'assistant',text:state.work.openings[state.opening].text}];stashSession();const row=state.sessions.find(x=>x.id===state.activeSession);if(row)row.draft='';close();render()}};
function closeIfOpen(){if(dialog.open)close()}
function openWork(id){stashSession();stashDraft();const w=works.find(w=>w.id===id);if(!w)return false;closeIfOpen();state.work=w;state.selectedCast=0;state.opening=0;state.detail='info';state.view='detail';history.replaceState(null,'','#work/'+encodeURIComponent(id));render(true);window.scrollTo(0,0);return true}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el&&!el.disabled)actions[el.dataset.action]?.(el)});
document.addEventListener('input',event=>{if(event.target.dataset?.draft)changeDraft(event.target.dataset.draft,event.target.value);if(event.target.id==='message-input'){const r=state.sessions.find(x=>x.id===state.activeSession);if(r)r.draft=event.target.value}if(event.target.id==='collection-search'){state.collectionQuery=event.target.value;render();document.querySelector('#collection-search').focus()}if(event.target.id==='search'){let value=event.target.value,position=event.target.selectionStart;state.query=value;render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(position,position)}});
document.addEventListener('change',event=>{if(event.target.id==='chat-character-image'){state.chatArt=event.target.value;render()}if(event.target.id==='settings-font'){state.font=Number(event.target.value);render()}if(event.target.id==='settings-art'){state.art=event.target.checked;render()}if(event.target.dataset?.draft)changeDraft(event.target.dataset.draft,event.target.value);if(event.target.id==='test-consent'){dialog.querySelector('[data-action="complete-checkout"]').disabled=!event.target.checked;}if(event.target.id==='opening'){state.opening=Number(event.target.value);render();document.querySelector('#opening')?.focus()}if(event.target.id==='setup-opening'){state.opening=Number(event.target.value);dialog.querySelector('#setup-preview').innerHTML=dialogue(state.work.openings[state.opening].text,!state.work.demoLocal)}});
document.addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='message-form')send(document.querySelector('#message-input').value)});
document.addEventListener('keydown',event=>{if(event.target.matches('[role="tab"]')&&['ArrowRight','ArrowLeft','Home','End'].includes(event.key)){event.preventDefault();const tabs=[...event.target.closest('[role="tablist"]').querySelectorAll('[role="tab"]')];let i=tabs.indexOf(event.target);i=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;actions[tabs[i].dataset.action]?.(tabs[i]);return}if(event.target.id==='message-input'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();send(event.target.value)}});
dialog.addEventListener('click',event=>{if(event.target===dialog){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)close()}});
dialog.addEventListener('cancel',event=>{event.preventDefault();close()});
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');state.paused=reduced.matches;
setInterval(()=>{if(state.view==='home'&&!state.paused&&!dialog.open&&document.visibilityState==='visible'&&!document.querySelector('.featured-work')?.matches(':focus-within,:hover')&&document.activeElement?.id!=='search'){state.feature=(state.feature+1)%featured().length;render()}},6500);
function readHash(){try{return location.hash.startsWith('#work/')?decodeURIComponent(location.hash.slice(6)):null}catch{return null}}
function routeHash(){const id=readHash();if(id){openWork(id);return}const hash=location.hash.slice(1);if(['works','chats','settings','studio'].includes(hash)){navigate(hash);return}if(hash.startsWith('chat/')){const id=hash.slice(5);if(state.sessions.some(r=>r.id===id)){actions['resume-chat']({dataset:{id}});return}}if(hash.startsWith('local-work/')){const id=hash.slice(11);if(state.localWorks.some(r=>r.id===id&&r.preview)){actions['open-local-work']({dataset:{id}});return}}if(hash.startsWith('chat/')||hash.startsWith('local-work/')){navigate(hash.startsWith('chat/')?'chats':'works');notify('이 탭의 기록이 없어요. 새로고침하면 목업 기록은 초기화됩니다.');return}actions.home()}
window.addEventListener('hashchange',routeHash);render();if(location.hash)routeHash();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'open_demo_work',description:'Open a public catalog work in the Onseo presentation mockup. Does not begin a chat or change saved data.',inputSchema:{type:'object',properties:{workId:{type:'string',enum:works.map(w=>w.id)}},required:['workId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.workId!=='string'||!works.some(w=>w.id===input.workId)||Object.keys(input).some(k=>k!=='workId'))throw new Error('Choose a valid public workId.');openWork(input.workId);return{view:state.view,title:state.work.title,demo:true}}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}
